WITH PARAMS AS ( SELECT CASE WHEN LEFT(TRIM(COALESCE(:VAR_DATA_INICIO, '')), 10) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(LEFT(TRIM(:VAR_DATA_INICIO), 10), '%d/%m/%Y') WHEN LEFT(TRIM(COALESCE(:VAR_DATA_INICIO, '')), 10) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN DATE(LEFT(TRIM(:VAR_DATA_INICIO), 10)) ELSE NULL END AS DT_INI_IN, CASE WHEN LEFT(TRIM(COALESCE(:VAR_DATA_FIM, '')), 10) REGEXP '^[0-9]{2}/[0-9]{2}/[0-9]{4}$' THEN STR_TO_DATE(LEFT(TRIM(:VAR_DATA_FIM), 10), '%d/%m/%Y') WHEN LEFT(TRIM(COALESCE(:VAR_DATA_FIM, '')), 10) REGEXP '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN DATE(LEFT(TRIM(:VAR_DATA_FIM), 10)) ELSE NULL END AS DT_FIM_IN ), D AS ( SELECT LEAST(DT_INI, DT_FIM) AS DT_INI, GREATEST(DT_INI, DT_FIM) AS DT_FIM, YEAR(GREATEST(DT_INI, DT_FIM)) AS ANO_ATU, YEAR(GREATEST(DT_INI, DT_FIM)) - 1 AS ANO_ANT, DATE_SUB(LEAST(DT_INI, DT_FIM), INTERVAL 1 YEAR) AS DT_INI_ANT, DATE_SUB(GREATEST(DT_INI, DT_FIM), INTERVAL 1 YEAR) AS DT_FIM_ANT FROM ( SELECT COALESCE(DT_FIM_IN, CURDATE()) AS DT_FIM, COALESCE(DT_INI_IN, MAKEDATE(YEAR(COALESCE(DT_FIM_IN, CURDATE())), 1)) AS DT_INI FROM PARAMS ) X ), base_bal AS ( SELECT CTACTB, SUM(CASE WHEN DATE(REFERENCIA) BETWEEN (SELECT DT_INI FROM D) AND (SELECT DT_FIM FROM D) THEN VLRLANC ELSE 0 END) AS ano_atu, SUM(CASE WHEN DATE(REFERENCIA) BETWEEN (SELECT DT_INI_ANT FROM D) AND (SELECT DT_FIM_ANT FROM D) THEN VLRLANC ELSE 0 END) AS ano_ant, SUM(CASE WHEN DATE(REFERENCIA) <= (SELECT DT_FIM FROM D) THEN VLRLANC ELSE 0 END) AS acum_atu, SUM(CASE WHEN DATE(REFERENCIA) <= (SELECT DT_FIM_ANT FROM D) THEN VLRLANC ELSE 0 END) AS acum_ant, SUM(CASE WHEN DATE(REFERENCIA) < (SELECT DT_INI FROM D) THEN VLRLANC ELSE 0 END) AS abert_atu, SUM(CASE WHEN DATE(REFERENCIA) < (SELECT DT_INI_ANT FROM D) THEN VLRLANC ELSE 0 END) AS abert_ant FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE GROUP BY CTACTB ), linhas AS ( SELECT DET.ID AS ID_DET, DET.ORDEM, DET.NOME_GRUPO, DET.VARIACAO FROM ESTR_DEMONSTRATIVOS EST INNER JOIN DET_DEMONSTRATIVO DET ON EST.ID = DET.ID_ESTR_DEMONSTRATIVO WHERE EST.ID = 10 ), ref_atu AS ( SELECT L.ID_DET, (SELECT R.ID FROM DET_DEMONSTRATIVO_REFERENCIA R WHERE R.ID_DET_DEMONSTRATIVO = L.ID_DET AND (CASE WHEN R.ANO_REFERENCIA > 10000 THEN FLOOR(R.ANO_REFERENCIA / 10000) ELSE R.ANO_REFERENCIA END) <= (SELECT ANO_ATU FROM D) ORDER BY (CASE WHEN R.ANO_REFERENCIA > 10000 THEN FLOOR(R.ANO_REFERENCIA / 10000) ELSE R.ANO_REFERENCIA END) DESC, R.ANO_REFERENCIA DESC, R.ID DESC LIMIT 1) AS ID_REF FROM linhas L ), ref_ant AS ( SELECT ID_DET, ID_REF FROM ref_atu ), regras_atu AS ( SELECT DISTINCT L.ORDEM, C.PADRAO_CTACTB, C.SINAL FROM linhas L INNER JOIN ref_atu RV ON RV.ID_DET = L.ID_DET INNER JOIN DET_DEMONSTRATIVO_CTACTB C ON C.ID_DET_DEMONSTRATIVO_REFERENCIA = RV.ID_REF ), regras_ant AS ( SELECT DISTINCT L.ORDEM, C.PADRAO_CTACTB, C.SINAL FROM linhas L INNER JOIN ref_ant RV ON RV.ID_DET = L.ID_DET INNER JOIN DET_DEMONSTRATIVO_CTACTB C ON C.ID_DET_DEMONSTRATIVO_REFERENCIA = RV.ID_REF ), qtd_atu AS ( SELECT ORDEM, COUNT(*) AS QTD FROM regras_atu GROUP BY ORDEM ), qtd_ant AS ( SELECT ORDEM, COUNT(*) AS QTD FROM regras_ant GROUP BY ORDEM ), val_atu AS ( SELECT R.ORDEM, SUM(IFNULL(B.ano_atu, 0) * R.SINAL) AS ano_v, SUM(IFNULL(B.acum_atu, 0) * R.SINAL) AS acum_v, SUM(IFNULL(B.abert_atu, 0) * R.SINAL) AS acum_ant_v FROM regras_atu R LEFT JOIN base_bal B ON B.CTACTB = R.PADRAO_CTACTB GROUP BY R.ORDEM ), val_ant AS ( SELECT R.ORDEM, SUM(IFNULL(B.ano_ant, 0) * R.SINAL) AS ano_v, SUM(IFNULL(B.acum_ant, 0) * R.SINAL) AS acum_v, SUM(IFNULL(B.abert_ant, 0) * R.SINAL) AS acum_ant_v FROM regras_ant R LEFT JOIN base_bal B ON B.CTACTB = R.PADRAO_CTACTB GROUP BY R.ORDEM ), exc_atu AS ( SELECT L.ORDEM, SUM(CASE WHEN DATE(B.REFERENCIA) BETWEEN (SELECT DT_INI FROM D) AND (SELECT DT_FIM FROM D) THEN ABS(IFNULL(B.VLRLANC, 0)) * EXC.SINAL ELSE 0 END) AS V FROM linhas L INNER JOIN ref_atu RV ON RV.ID_DET = L.ID_DET INNER JOIN DET_DEMONSTRATIVO_CTACTB_EXC EXC ON EXC.ID_DET_DEMONSTRATIVO_REFERENCIA = RV.ID_REF LEFT JOIN IMP_BASE_BALANCETE B ON B.CTACTB = EXC.PADRAO_CTACTB AND B.CODEMP = :VAR_EMPRESA_DRE GROUP BY L.ORDEM ), exc_ant AS ( SELECT L.ORDEM, SUM(CASE WHEN DATE(B.REFERENCIA) BETWEEN (SELECT DT_INI_ANT FROM D) AND (SELECT DT_FIM_ANT FROM D) THEN ABS(IFNULL(B.VLRLANC, 0)) * EXC.SINAL ELSE 0 END) AS V FROM linhas L INNER JOIN ref_ant RV ON RV.ID_DET = L.ID_DET INNER JOIN DET_DEMONSTRATIVO_CTACTB_EXC EXC ON EXC.ID_DET_DEMONSTRATIVO_REFERENCIA = RV.ID_REF LEFT JOIN IMP_BASE_BALANCETE B ON B.CTACTB = EXC.PADRAO_CTACTB AND B.CODEMP = :VAR_EMPRESA_DRE GROUP BY L.ORDEM ), outros AS ( SELECT SUM(CASE WHEN DATE(REFERENCIA) BETWEEN (SELECT DT_INI FROM D) AND (SELECT DT_FIM FROM D) THEN VLRLANC ELSE 0 END) AS v_atu, SUM(CASE WHEN DATE(REFERENCIA) BETWEEN (SELECT DT_INI_ANT FROM D) AND (SELECT DT_FIM_ANT FROM D) THEN VLRLANC ELSE 0 END) AS v_ant FROM OUTROS_DFC WHERE CODEMP = :VAR_EMPRESA_DRE ) SELECT L.ORDEM, L.NOME_GRUPO AS DESCRICAO, L.VARIACAO, (CASE WHEN QA.QTD IS NULL AND TRIM(L.ORDEM) <> '1.9.1' THEN NULL ELSE (CASE WHEN TRIM(L.ORDEM) = '1.9.1' AND IFNULL(VA.ano_v, 0) = 0 THEN IFNULL((SELECT v_atu FROM outros), 0) WHEN TRIM(L.ORDEM) = '5.1' THEN VA.acum_ant_v WHEN TRIM(L.ORDEM) = '5.2' THEN VA.acum_v WHEN L.VARIACAO = 'Sim' THEN VA.acum_ant_v - VA.acum_v ELSE VA.ano_v END) - IFNULL(EA.V, 0) END) / 1000 AS VALOR_ANO_ATUAL, (CASE WHEN QB.QTD IS NULL AND TRIM(L.ORDEM) <> '1.9.1' THEN NULL ELSE (CASE WHEN TRIM(L.ORDEM) = '1.9.1' AND IFNULL(VB.ano_v, 0) = 0 THEN IFNULL((SELECT v_ant FROM outros), 0) WHEN TRIM(L.ORDEM) = '5.1' THEN VB.acum_ant_v WHEN TRIM(L.ORDEM) = '5.2' THEN VB.acum_v WHEN L.VARIACAO = 'Sim' THEN VB.acum_ant_v - VB.acum_v ELSE VB.ano_v END) - IFNULL(EB.V, 0) END) / 1000 AS VALOR_ANO_ANTERIOR, (SELECT DT_INI FROM D) AS DATA_INICIO_USADA, (SELECT DT_FIM FROM D) AS DATA_FIM_USADA, (SELECT ANO_ATU FROM D) AS ANO_ATU, (SELECT COUNT(*) FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE) AS LANC_EMPRESA, (SELECT COUNT(*) FROM IMP_BASE_BALANCETE WHERE CODEMP = :VAR_EMPRESA_DRE AND DATE(REFERENCIA) BETWEEN (SELECT DT_INI FROM D) AND (SELECT DT_FIM FROM D)) AS LANC_PERIODO, CASE WHEN (SELECT DT_INI_IN FROM PARAMS) IS NULL OR (SELECT DT_FIM_IN FROM PARAMS) IS NULL THEN 0 ELSE 1 END AS DATAS_OK FROM linhas L LEFT JOIN qtd_atu QA ON QA.ORDEM = L.ORDEM LEFT JOIN qtd_ant QB ON QB.ORDEM = L.ORDEM LEFT JOIN val_atu VA ON VA.ORDEM = L.ORDEM LEFT JOIN val_ant VB ON VB.ORDEM = L.ORDEM LEFT JOIN exc_atu EA ON EA.ORDEM = L.ORDEM LEFT JOIN exc_ant EB ON EB.ORDEM = L.ORDEM ORDER BY L.ORDEM LIMIT 500;